def sync_manifest() -> None:
    data = json.loads(AUDIO_MANIFEST.read_text(encoding="utf-8"))
    rows = data["recordings"]
    by_phrase = {row["phrase"]: row for row in rows}
    next_id = max(int(row["id"].split("-")[1]) for row in rows) + 1
    wanted: dict[str, set[str]] = {}
    for stem, _, localized in LESSONS:
        names = {"ru": f"{stem}.md", "kz": f"{stem}-kz.md", "en": f"{stem}-en.md"}
        for lang, lesson in localized.items():
            for phrase, _ in lesson["phrases"]:
                wanted.setdefault(phrase, set()).add(names[lang])
    for phrase, files in wanted.items():
        row = by_phrase.get(phrase)
        if row is None:
            row = {"id": f"kz-{next_id:03d}", "phrase": phrase, "file": f"kz-{next_id:03d}.wav", "status": "candidate_review", "lessons": []}
            rows.append(row); by_phrase[phrase] = row; next_id += 1
        row["lessons"] = sorted(set(row.get("lessons", [])) | files)
    AUDIO_MANIFEST.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def render(lang: str, data: dict, map_stem: str, next_entry, audio: dict[str, str]) -> str:
    ui, common = UI[lang], COMMON[lang]
    parts = [f"# {data['title']}", "", f"_Lead (summary):_ **{data['lead']}**", "", f"## {ui[0]}", "", common["map"], "", f"![{data['title']}](/static/course/kazakh-language/map-{map_stem}-{lang}.svg)", "", f"## {ui[1]}", "", data["situation"], "", f"## {ui[2]}", ""]
    for phrase, meaning in data["phrases"]:
        parts += [f"[{ui[16]}: {phrase}]({audio[phrase]}) — {meaning}", ""]
    sections = [(ui[3], common["workflow"]), (ui[4], data["model"]), (ui[5], "```kazakh\n" + data["support"] + "\n```"), (ui[6], data["limit"]), (ui[7], common["predict"]), (ui[8], common["recall"]), (ui[9], data["mistake"]), (ui[10], common["transfer"]), (ui[11], data["project"]), (ui[12], data["task"])]
    for heading, body in sections: parts += [f"## {heading}", "", body, ""]
    parts += [f"## {ui[13]}", ""] + [f"- {line}" for line in common["repeat"]]
    if next_entry: parts += ["", f"[{ui[14]}: {next_entry[2][lang]['title']}](/read/kazakh-language-{next_entry[0]}?lang={lang})"]
    else: parts += ["", f"[{ui[15]}](/course/kazakh-language?lang={lang})"]
    return "\n".join(parts).strip() + "\n"


def main() -> None:
    if len(LESSONS) != 8: raise ValueError("space-cases block must contain exactly eight lessons")
    sync_manifest()
    audio = {row["phrase"]: AUDIO_PREFIX + row["file"] for row in json.loads(AUDIO_MANIFEST.read_text())["recordings"]}
    for index, (stem, map_stem, localized) in enumerate(LESSONS):
        next_entry = LESSONS[index + 1] if index + 1 < len(LESSONS) else None
        for lang, data in localized.items():
            suffix = "" if lang == "ru" else f"-{lang}"
            (OUT / f"{stem}{suffix}.md").write_text(render(lang, data, map_stem, next_entry, audio), encoding="utf-8")
    print(f"Generated {len(LESSONS) * 3} localized Space and Cases pages")


if __name__ == "__main__": main()
